def guide_hub(lang,P):
    present=[c for c in GCAT_ORDER if c=='all' or any(c in GUIDE_CATS.get(g['slug'],[]) for g in GUIDES)]
    chips=''.join(f'<button type="button" class="gchip" data-filter="{c}" aria-pressed="{"true" if c=="all" else "false"}">{GCAT[c][lang]}</button>' for c in present)
    cards=''
    for g in GUIDES:
        cats=' '.join(GUIDE_CATS.get(g['slug'],[]))
        href=u(P,lang,'how-to-elope-in-the-europe-mountains/'+g['slug']+'/')
        _im=bild(P,f"img/stories/{g['img']}.webp",g["title"][lang],sizes="(max-width:520px) 100vw, (max-width:860px) 50vw, 380px")
        cards+=(f'<a class="gcard reveal" data-cat="{cats}" href="{href}">'
                f'<div class="imgwrap">{_im}</div>'
                f'<div class="no">{t(lang,"guide_kick")}</div><h3>{g["title"][lang]}</h3>'
                f'<div class="gcard-x">{g["excerpt"][lang]}</div></a>')
    return ('<div class="page-plain" style="border-bottom:0"><div class="wrap">'
            f'<div class="kicker" data-n="{t(lang,"gd_k")}"><span class="line"></span></div>'
            f'<h2 class="gd-h2" style="font-size:clamp(30px,4.4vw,52px)">{t(lang,"gd_h")}</h2><p class="lead">{t(lang,"ht_start_copy")}</p>'
            f'<div class="guide-filters" id="guideFilters" aria-label="Guide filters">{chips}</div></div></div>'
            f'<section style="padding-top:clamp(24px,3vw,40px)"><div class="wrap"><div class="guide-grid" id="guideGrid">{cards}</div></div></section>')

def guide_mosaic(lang,P):
    cls=['m-tile m-w','m-tile m-n','m-tile m-n','m-tile m-w']
    tiles=''
    for i,g in enumerate(GUIDES):
        c=cls[i] if i<len(cls) else 'm-tile'
        href=u(P,lang,'how-to-elope-in-the-europe-mountains/'+g['slug']+'/')
        _im=bild(P,f"img/stories/{g['img']}.webp",g["title"][lang],sizes="(max-width:520px) 100vw, (max-width:860px) 50vw, 380px")
        tiles+=(f'<a class="{c} reveal" href="{href}">{_im}'
                f'<div class="m-cap"><div class="m-cat">{t(lang,"guide_kick")}</div><h3>{g["title"][lang]}</h3></div></a>')
    return '<div class="mosaic">'+tiles+'</div>'

def linkify(text,lang,P):
    """Turn [[g:slug|label]] / [[s:slug|label]] / [[c:cat|label]] tokens into internal links."""
    def _r(m):
        k,slug,label=m.group(1),m.group(2),m.group(3)
        rel={'g':'how-to-elope-in-the-europe-mountains/'+slug+'/',
             's':'portfolio-item/'+slug+'/',
             'c':'portfolio-category/'+slug+'/'}.get(k)
        return f'<a href="{u(P,lang,rel)}">{label}</a>' if rel else label
    return re.sub(r'\[\[([gsc]):([a-z0-9-]+)\|([^\]|]+)\]\]',_r,text)

def sun_times_block(lang):
    # Approximate sunrise/sunset for the Dolomites (~46.5°N, local time), mid-month.
    ROWS=[('may','05:45','20:40'),('jun','05:25','21:05'),('jul','05:40','21:00'),
          ('aug','06:10','20:25'),('sep','06:45','19:25'),('oct','07:20','18:25')]
    MONTH={'may':{'en':'May','de':'Mai','es':'Mayo','it':'Maggio'},
           'jun':{'en':'June','de':'Juni','es':'Junio','it':'Giugno'},
           'jul':{'en':'July','de':'Juli','es':'Julio','it':'Luglio'},
           'aug':{'en':'August','de':'August','es':'Agosto','it':'Agosto'},
           'sep':{'en':'September','de':'September','es':'Septiembre','it':'Settembre'},
           'oct':{'en':'October','de':'Oktober','es':'Octubre','it':'Ottobre'}}
    ST={'h':{'en':'Sunrise &amp; sunset times (May&ndash;October)',
             'de':'Sonnenauf- und Sonnenuntergangszeiten (Mai&ndash;Oktober)',
             'es':'Horas de amanecer y atardecer (mayo&ndash;octubre)',
             'it':'Orari di alba e tramonto (maggio&ndash;ottobre)'},
        'intro':{'en':'Approximate local times for the Dolomites (around Cortina d&rsquo;Ampezzo). High peaks and valley walls can shift the light you actually see by 20&ndash;40 minutes, so always plan a buffer.',
                 'de':'Ungefähre Ortszeiten für die Dolomiten (Raum Cortina d&rsquo;Ampezzo). Hohe Gipfel und Talwände können das tatsächlich sichtbare Licht um 20&ndash;40 Minuten verschieben &mdash; plant also immer einen Puffer ein.',
                 'es':'Horas locales aproximadas para los Dolomitas (zona de Cortina d&rsquo;Ampezzo). Las cumbres altas y las paredes del valle pueden desplazar la luz real 20&ndash;40 minutos, así que planificad siempre un margen.',
                 'it':'Orari locali approssimativi per le Dolomiti (zona di Cortina d&rsquo;Ampezzo). Cime alte e pareti della valle possono spostare la luce reale di 20&ndash;40 minuti, quindi pianificate sempre un margine.'},
        'month':{'en':'Month','de':'Monat','es':'Mes','it':'Mese'},
        'sunrise':{'en':'Sunrise','de':'Sonnenaufgang','es':'Amanecer','it':'Alba'},
        'sunset':{'en':'Sunset','de':'Sonnenuntergang','es':'Atardecer','it':'Tramonto'},
        'note':{'en':'Golden hour &mdash; the soft, warm light couples love &mdash; falls roughly in the 30&ndash;40 minutes after sunrise and before sunset. Times are Central European Summer Time (CEST); the clocks go back one hour in late October.',
                'de':'Die goldene Stunde &mdash; das weiche, warme Licht &mdash; liegt etwa in den 30&ndash;40 Minuten nach Sonnenaufgang und vor Sonnenuntergang. Die Zeiten gelten in Mitteleuropäischer Sommerzeit (MESZ); Ende Oktober wird eine Stunde zurückgestellt.',
                'es':'La hora dorada &mdash; la luz suave y cálida &mdash; cae aproximadamente en los 30&ndash;40 minutos tras el amanecer y antes del atardecer. Las horas son de verano de Europa Central (CEST); a finales de octubre se atrasa una hora.',
                'it':'L&rsquo;ora d&rsquo;oro &mdash; la luce morbida e calda &mdash; cade all&rsquo;incirca nei 30&ndash;40 minuti dopo l&rsquo;alba e prima del tramonto. Gli orari sono in ora legale dell&rsquo;Europa centrale (CEST); a fine ottobre si torna indietro di un&rsquo;ora.'}}
    H2='font-family:var(--serif);font-weight:400;font-size:clamp(25px,3vw,36px);letter-spacing:-.01em;margin:1.5em 0 .35em'
    rows=''.join(f'<tr><td>{MONTH[m][lang]}</td><td>{sr}</td><td>{ss}</td></tr>' for m,sr,ss in ROWS)
    return (f'<h2 style="{H2}">{ST["h"][lang]}</h2>'
            f'<p style="color:var(--ink-2)">{ST["intro"][lang]}</p>'
            f'<div style="overflow-x:auto"><table class="suntimes"><thead><tr>'
            f'<th>{ST["month"][lang]}</th><th>{ST["sunrise"][lang]}</th><th>{ST["sunset"][lang]}</th></tr></thead>'
            f'<tbody>{rows}</tbody></table></div>'
            f'<p style="color:var(--ink-2);font-size:14px">{ST["note"][lang]}</p>')

def build_guides(lang):
    for g in GUIDES:
        if g['slug'] in ('helicopter-elopement-dolomites-guide','mountain-proposal-guide','sunrise-or-sunset-elopement','most-beautiful-dolomites-spots','how-to-plan-your-elopement','best-alps-elopement-locations'):
            continue   # rendered by dedicated rich renderers
        ex=GUIDE_EXTRA[g['slug']]
        rel='how-to-elope-in-the-europe-mountains/'+g['slug']+'/'; P=prefix(lang,rel)
        facts='<div class="facts">'+''.join(f'<div class="fct"><div class="fl">{LBL[k][lang]}</div><div class="fv">{val[lang]}</div></div>' for k,val in ex['facts'])+'</div>'
        allsec=g['sec']+[ex['sec4']]
        secs=''
        for s in allsec:
            secs+=(f'<h2 style="font-family:var(--serif);font-weight:400;font-size:clamp(25px,3vw,36px);letter-spacing:-.01em;margin:1.5em 0 .35em">{s["h"][lang]}</h2>'
                   f'<p style="color:var(--ink-2)">{linkify(s["p"][lang],lang,P)}</p>')
        tips='<div class="tips"><h4>'+t(lang,'good_to_know')+'</h4><ul>'+''.join('<li>'+linkify(it,lang,P)+'</li>' for it in ex['tips'][lang])+'</ul></div>'
        suntimes=sun_times_block(lang) if g['slug']=='sunrise-or-sunset-elopement' else ''
        related=''.join(story_card(lang,P,STORYBY[sl]) for sl in ex['stories'])
        more=''.join(guide_card(lang,P,x) for x in GUIDES if x['slug']!=g['slug'])
        _gimg=f"img/stories/{g['img']}.webp"
        _hero=herobg(P,_gimg,g["title"][lang])
        body=(nav(lang,rel,'howto')+
          f'<section class="page-hero" style="padding:0">{_hero}'
          f'<div class="content"><div class="wrap"><div class="kicker" data-n="{t(lang,"guide_kick")}"><span class="line"></span></div><h1>{g["title"][lang]}</h1></div></div></section>'
          '<section><div class="wrap" style="max-width:820px">'
          f'<p class="lead">{linkify(g["intro"][lang],lang,P)}</p>'
          f'<div class="cap" style="margin:0 0 -14px">{t(lang,"quick_facts")}</div>{facts}'
          f'{secs}{suntimes}{tips}'
          f'<p style="margin-top:2.4em"><a href="{u(P,lang,"how-to-elope-in-the-europe-mountains/")}" class="arrow-link">&larr; {T["nav"]["howto"][lang]}</a></p></div></section>'
          '<section style="padding-top:0"><div class="wrap"><div class="section-head reveal">'
          f'<div class="kicker" data-n="{t(lang,"related_stories")}"><span class="line"></span></div><h2>{t(lang,"related_stories")}</h2></div>'
          f'<div class="story-grid">{related}</div></div></section>'
          '<section class="stories" style="padding-top:clamp(40px,6vw,80px)"><div class="wrap"><div class="section-head reveal">'
          f'<div class="kicker" data-n="{t(lang,"more_guides")}"><span class="line"></span></div><h2>{t(lang,"more_guides")}</h2></div>'
          f'<div class="story-grid">{more}</div></div></section>'
          '<section class="cta"><div class="wrap row reveal"><div>'
          f'<div class="kicker" data-n="{t(lang,"cta_k")}"><span class="line"></span></div><h2 style="margin-top:20px">{t(lang,"cta_h")}</h2></div>'
          f'<a href="{u(P,lang,"get-in-touch/")}" class="btn light">{t(lang,"start_planning")}</a></div></section>'
          +footer(lang,rel))
        write(lang,rel,head(lang,rel,g['title'][lang]+' — Mountain Elopement',g['excerpt'][lang],pre=herolink(P,_gimg))+body+scripts(P))

